#!/usr/bin/env python3
from __future__ import annotations

import json
import re
from pathlib import Path


TASK_ID = "CSX-039_Q2"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = Path(__file__).resolve().parents[3]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-039"

OPEN_METEO = "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive_cold_variables.json"
REPORT_HTML = "data/event_reports/event_reports_004_01_Locked_package_evidence_report.html.html"
GPM_STATS = "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json"
CHIRPS_STATS = "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json"
ALPHAEARTH_CHANGE = "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json"


def load_json(rel_path: str) -> dict:
    with (PACKAGE_DIR / rel_path).open("r", encoding="utf-8-sig") as f:
        return json.load(f)


def strip_html(text: str) -> str:
    text = re.sub(r"<script.*?</script>", " ", text, flags=re.I | re.S)
    text = re.sub(r"<style.*?</style>", " ", text, flags=re.I | re.S)
    text = re.sub(r"<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", text)


def number_from_report(pattern: str, text: str) -> float:
    match = re.search(pattern, text, flags=re.I)
    if not match:
        raise ValueError(f"missing report pattern: {pattern}")
    token = match.group(1).lower()
    words = {
        "one": 1.0,
        "two": 2.0,
        "three": 3.0,
        "four": 4.0,
        "five": 5.0,
        "six": 6.0,
        "seven": 7.0,
        "eight": 8.0,
        "nine": 9.0,
        "ten": 10.0,
    }
    if token in words:
        return words[token]
    return float(token)


def longest_true_run(values: list[bool]) -> int:
    best = 0
    current = 0
    for value in values:
        if value:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def build_rubric() -> dict:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Source-role mapping",
                "points": 3,
                "description": "Uses the point weather file, report HTML, GPM, CHIRPS, and annual embedding-change product for their intended numeric roles.",
                "partial_credit": "Partial credit for using most source roles correctly while confusing one gridded or embedding product.",
            },
            {
                "name": "Low-point cold and wind ledger",
                "points": 4,
                "description": "Computes the low-point snowfall, cold-hour count, maximum gust, gust-hour count, and gust-energy proxy correctly.",
                "partial_credit": "Partial credit for small rounding errors or for getting only the temperature or wind half of the ledger correct.",
            },
            {
                "name": "Report snow and rain conversions",
                "points": 4,
                "description": "Extracts and converts the report snow and rain anchors, including the high-mountain snow and local rainfall range.",
                "partial_credit": "Partial credit for correct extraction but one unit conversion or ratio error.",
            },
            {
                "name": "Grid-report gap ratios",
                "points": 3,
                "description": "Compares report rainfall with GPM and CHIRPS maxima and reports the near-fivefold gap ratios.",
                "partial_credit": "Partial credit for identifying the gap direction but missing one exact ratio.",
            },
            {
                "name": "Embedding-change separation",
                "points": 3,
                "description": "Uses the annual embedding mean, maximum, and max-to-mean ratio as a separate landscape-change check, not as event-window precipitation.",
                "partial_credit": "Partial credit for computing the values but blending them with the precipitation diagnosis.",
            },
            {
                "name": "Final compact diagnosis",
                "points": 3,
                "description": "Returns the requested compact answer with a label equivalent to report_grid_gap_with_elevation_snow_gradient.",
                "partial_credit": "Partial credit for a compatible label with incomplete but mostly correct numeric support.",
            },
        ],
    }


def build_ground_truth() -> dict:
    meteo = load_json(OPEN_METEO)
    hourly = meteo["hourly"]
    temps = [float(x) for x in hourly["temperature_2m"]]
    gusts = [float(x) for x in hourly["wind_gusts_10m"]]
    snowfall_cm = [float(x) for x in hourly["snowfall"]]

    low_point_snow_cm = round(sum(snowfall_cm), 2)
    low_point_snow_in = low_point_snow_cm / 2.54
    temp_hours_le4 = sum(1 for x in temps if x <= 4.0)
    temp_longest_le4 = longest_true_run([x <= 4.0 for x in temps])
    max_gust = max(gusts)
    gust_hours_ge65 = sum(1 for x in gusts if x >= 65.0)
    gust_kmh2 = max_gust**2

    report_text = strip_html((PACKAGE_DIR / REPORT_HTML).read_text(encoding="utf-8", errors="ignore"))
    high_snow_ft = number_from_report(r"recorded nearly\s+([0-9.]+)\s+feet", report_text)
    lacrescenta_snow_in = number_from_report(
        r"([0-9.]+|one|two|three|four|five|six|seven|eight|nine|ten)\s+inches fell in La Crescenta",
        report_text,
    )
    beverly_rain_in = number_from_report(
        r"Beverl[ey]+ Hills saw\s+([0-9.]+|one|two|three|four|five|six|seven|eight|nine|ten)\s+inches of rain",
        report_text,
    )
    downtown_rain_in = number_from_report(
        r"downtown Los Angeles saw\s+([0-9.]+|one|two|three|four|five|six|seven|eight|nine|ten)\s+inches",
        report_text,
    )

    high_snow_in = high_snow_ft * 12.0
    rain_min_in = min(beverly_rain_in, downtown_rain_in)
    rain_max_in = max(beverly_rain_in, downtown_rain_in)
    rain_min_mm = rain_min_in * 25.4
    rain_max_mm = rain_max_in * 25.4

    gpm_max = float(load_json(GPM_STATS)["stats"]["gpm_event_precip_mm_max"])
    chirps_max = float(load_json(CHIRPS_STATS)["stats"]["chirps_event_precip_mm_max"])
    alpha_stats = load_json(ALPHAEARTH_CHANGE)["stats"]
    alpha_mean = float(alpha_stats["alphaearth_1_minus_cosine_mean"])
    alpha_max = float(alpha_stats["alphaearth_1_minus_cosine_max"])

    low_point = {
        "snow_in": round(low_point_snow_in, 3),
        "temp_hours_le4": temp_hours_le4,
        "max_gust_kmh": round(max_gust, 1),
        "gust_hours_ge65": gust_hours_ge65,
        "gust_kmh2": round(gust_kmh2, 1),
    }
    snow_ratios = {
        "mountain_to_lacrescenta": round(high_snow_in / lacrescenta_snow_in, 1),
        "mountain_to_low_point": round(high_snow_in / low_point_snow_in, 1),
    }
    rain_mm = [round(rain_min_mm, 1), round(rain_max_mm, 1)]
    grid_gap = {
        "rain_min_to_chirps_max": round(rain_min_mm / chirps_max, 2),
        "rain_max_to_gpm_max": round(rain_max_mm / gpm_max, 2),
    }
    annual_embedding = {
        "mean": round(alpha_mean, 6),
        "max": round(alpha_max, 6),
        "max_to_mean": round(alpha_max / alpha_mean, 1),
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": "CSX-039",
        "task_type": "short_answer",
        "target_family": "cross_source_numeric_diagnosis",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": {
            "answer_label": "report_grid_gap_with_elevation_snow_gradient",
            "metrics": {
                "low_point": low_point,
                "report_snow_in": {
                    "high_elevation": high_snow_in,
                    "la_crescenta": lacrescenta_snow_in,
                },
                "snow_ratios": snow_ratios,
                "rain_mm_range": rain_mm,
                "grid_gap_ratios": grid_gap,
                "annual_embedding_change": annual_embedding,
            },
            "decisive_tests": [
                "The report rainfall range is about five times the GPM and CHIRPS event maxima used in the package summary.",
                "The snow gradient is much larger than the low-point snow amount: 48.0x from high mountain to La Crescenta and 316.7x from high mountain to the 90 m point.",
            ],
            "data_read": {
                "point_weather": OPEN_METEO,
                "report_snow_and_rain": REPORT_HTML,
                "gpm_precipitation_max": GPM_STATS,
                "chirps_precipitation_max": CHIRPS_STATS,
                "annual_embedding_change": ALPHAEARTH_CHANGE,
            },
        },
        "event": {
            "package_id": "CSX-039",
            "event_name": "February 2023 Southern California winter storm",
            "hazard_family": "cold_wave_winter_storm",
            "event_window": "2023-02-23 to 2023-02-26",
        },
        "decision_rule": {
            "summary": "The final label must be driven by the near-fivefold report-to-grid rainfall gaps and the large elevation snow ratios; low-point wind and annual embedding change are secondary numeric checks.",
            "accepted_label_family": "report_grid_gap_with_elevation_snow_gradient",
        },
        "key_values": {
            "source_report_values": {
                "high_snow_ft": high_snow_ft,
                "high_snow_in": high_snow_in,
                "lacrescenta_snow_in": lacrescenta_snow_in,
                "rain_range_in": [rain_min_in, rain_max_in],
            },
            "source_grid_values": {
                "gpm_max_mm": round(gpm_max, 3),
                "chirps_max_mm": round(chirps_max, 3),
            },
            "source_point_values": {
                "elevation_m": float(meteo["elevation"]),
                "snow_cm": low_point_snow_cm,
                "temp_longest_le4_hours": temp_longest_le4,
            },
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                OPEN_METEO,
                REPORT_HTML,
                GPM_STATS,
                CHIRPS_STATS,
                ALPHAEARTH_CHANGE,
            ],
            "notes": "Values are rebuilt from local package files using unit conversion, hourly counts, and ratio checks.",
        },
    }


def main() -> None:
    computed = build_ground_truth()
    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(computed, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
